-- =============================================================
-- ledger —— D1 数据文件（seed）
-- 由原 MongoDB 数据库导出（2026-08-22，generated by exportD1.js），
-- 包含建表 + 全量业务数据，可直接用于本地 D1 初始化 / 线上迁移。
--
-- 注意：D1 不接受 SQL 层的 BEGIN/COMMIT 事务语句，故本文件不包裹事务；
--       每条语句独立执行，若中途失败需先清理（见 LOCAL_DEVELOPMENT.md）再整体重导。
-- 初始化：npm run db:local-seed
-- =============================================================

-- ===================== aa_big_type =====================
CREATE TABLE IF NOT EXISTS aa_big_type (
  _id TEXT PRIMARY KEY,
  id INTEGER,
  bname TEXT,
  btype INTEGER,
  bshow INTEGER,
  bpx INTEGER
);

-- ===================== aa_small_type =====================
CREATE TABLE IF NOT EXISTS aa_small_type (
  _id TEXT PRIMARY KEY,
  id INTEGER,
  bid INTEGER,
  sname TEXT,
  sshow INTEGER,
  spx INTEGER,
  _bid TEXT
);

-- ===================== aa_income =====================
CREATE TABLE IF NOT EXISTS aa_income (
  _id TEXT PRIMARY KEY,
  id INTEGER,
  bid TEXT,
  iname TEXT,
  iday TEXT,
  itime TEXT,
  cid INTEGER,
  imoney INTEGER,
  _bid TEXT,
  _iday TEXT,
  _itime TEXT
);

-- ===================== aa_pay_budget =====================
CREATE TABLE IF NOT EXISTS aa_pay_budget (
  _id TEXT PRIMARY KEY,
  id INTEGER,
  sid TEXT,
  pmoney INTEGER,
  pmonth TEXT,
  ptime TEXT,
  cid INTEGER,
  _sid TEXT,
  _pmonth TEXT,
  _ptime TEXT
);

-- ===================== aa_account_book =====================
CREATE TABLE IF NOT EXISTS aa_account_book (
  _id TEXT PRIMARY KEY,
  id INTEGER,
  sid TEXT,
  aname TEXT,
  amoney REAL,
  aday TEXT,
  atime TEXT,
  cid INTEGER,
  _sid TEXT,
  _aday TEXT,
  _atime TEXT,
  aday_ TEXT
);

-- 索引
CREATE INDEX IF NOT EXISTS idx_account_book_sid ON aa_account_book(_sid);
CREATE INDEX IF NOT EXISTS idx_account_book_aday ON aa_account_book(_aday);
CREATE INDEX IF NOT EXISTS idx_small_type_bid ON aa_small_type(_bid);
CREATE INDEX IF NOT EXISTS idx_income_bid ON aa_income(_bid);
CREATE INDEX IF NOT EXISTS idx_pay_budget_sid ON aa_pay_budget(_sid);

